"""Actual mouse/touch/keyboard orientation without locking the scroll journey."""
import json,math
from pathlib import Path
from playwright.sync_api import sync_playwright
OUT=Path('artifacts/house-look');OUT.mkdir(parents=True,exist_ok=True)
r={'checks':[],'errors':[],'assets':[]}
def check(name,ok,detail=None):
 r['checks'].append({'name':name,'passed':bool(ok),'detail':detail});print(name,ok,detail,flush=True);assert ok,name
def state(page):return page.locator('#casa').evaluate('e=>e.houseJourney.inspect()')
def settle(page):page.wait_for_function('()=>{const v=document.querySelector("#casa").houseJourney.inspect().view;return Math.abs(v.yaw-v.targetYaw)<.005&&Math.abs(v.pitch-v.targetPitch)<.005}')
def go(page,p):
 page.evaluate('''async p=>{const{t:ST}=await import('/assets/index-BXEErpTi.js?v=perf-1');const s=ST.getById('hipocampo-house');__hipocampoLenis.scrollTo(s.start+p*(s.end-s.start),{immediate:true});ST.update()}''',p)
 page.wait_for_function('p=>{const s=document.querySelector("#casa").houseJourney.inspect();return Math.abs(s.target-p)<.0004&&Math.abs(s.progress-s.target)<.000001}',arg=p)
def direction(page):return page.evaluate('__lookQA.camera.getWorldDirection(__lookQA.camera.position.clone()).toArray()')
def drag(page,x0,y0,x1,y1):
 page.mouse.move(x0,y0);page.mouse.down();page.mouse.move(x1,y1,steps=15);page.mouse.up();settle(page)
def open_page(browser,w,h,mobile=False,reduced=False):
 c=browser.new_context(viewport={'width':w,'height':h},is_mobile=mobile,has_touch=mobile,reduced_motion='reduce' if reduced else 'no-preference')
 page=c.new_page();page.on('pageerror',lambda e:r['errors'].append(str(e)));page.on('response',lambda e:r['assets'].append(e.url)if e.status>=400 and e.url.startswith('http://127.0.0.1:4173')else None)
 def instrument(route):
  response=route.fetch();body=response.text();route.fulfill(response=response,body=body.replace('  const maxAniso =','  window.__lookQA={camera,renderer};\n  const maxAniso =',1))
 page.route('**/assets/page3-house.js?*',instrument);page.goto('http://127.0.0.1:4173/',wait_until='networkidle');page.wait_for_function('document.querySelector("#casa")?.houseJourney?.inspect().prepared',timeout=60000);return c,page
try:
 with sync_playwright() as p:
  b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
  c,page=open_page(b,1600,900)
  go(page,.2);check('controles não aparecem antes de entrar',page.locator('.page3-look-controls').is_hidden())
  go(page,.72);page.wait_for_function('document.querySelector("#casa").houseJourney.inspect().view.available')
  base=direction(page);scroll=page.evaluate('scrollY');drag(page,600,350,1000,350)
  v=state(page)['view'];d=direction(page)
  check('arrastar gira a câmera real para o lado sem deslocar a página',abs(sum(a*b for a,b in zip(base,d)))<.15 and abs(page.evaluate('scrollY')-scroll)<2,{'view':v,'direction':d})
  page.screenshot(path=str(OUT/'look-left-1600.png'))
  for _ in range(2):drag(page,200,350,1400,350)
  check('giro continua além de 360 graus',state(page)['view']['yaw']>2*math.pi,state(page)['view'])
  drag(page,800,200,800,800);check('inclinação limitada, sem virar de cabeça para baixo',abs(state(page)['view']['pitch']-math.pi*.42)<.01,state(page)['view'])
  page.locator('.page3-look-reset').click();settle(page)
  check('voltar ao percurso recentra a câmera',not state(page)['view']['active'] and sum(a*b for a,b in zip(base,direction(page)))>.999)
  toggle=page.locator('.page3-look-toggle');toggle.click();y=page.evaluate('scrollY');toggle.press('ArrowLeft');toggle.press('ArrowUp');settle(page)
  check('setas permitem olhar com teclado sem rolar a página',state(page)['view']['yaw']>.1 and state(page)['view']['pitch']>.08 and abs(page.evaluate('scrollY')-y)<2)
  toggle.press('Escape');settle(page);check('Escape libera e recentra a visão',not state(page)['view']['active'] and abs(state(page)['view']['yaw'])<.005)
  toggle.click();drag(page,600,350,800,350);y=page.evaluate('scrollY');page.mouse.wheel(0,130);page.wait_for_function('y=>scrollY>y+20',arg=y)
  check('roda do mouse continua percorrendo a casa ao olhar',True)
  page.evaluate("()=>__hipocampoLenis.scrollTo(document.querySelector('#sobre'),{immediate:true})");page.wait_for_function('document.querySelector(".page3-look-controls").hidden')
  check('saída fecha os controles e libera a próxima seção',not state(page)['view']['active'] and page.locator('.page3-canvas').evaluate('e=>getComputedStyle(e).pointerEvents')=='none')
  go(page,.72);check('retornar à casa não restaura uma rotação antiga',not state(page)['view']['active'] and abs(state(page)['view']['yaw'])<.005)
  page.locator('.page3-look-toggle').click();drag(page,600,350,1100,350);go(page,.499)
  check('voltar para a porta encerra o modo de olhar antes da fachada',page.locator('.page3-look-controls').is_hidden() and not state(page)['view']['active'])
  go(page,.72)
  page.locator('.page3-look-toggle').click();page.mouse.move(600,350);page.mouse.down();page.mouse.move(800,350)
  page.evaluate("()=>__hipocampoLenis.scrollTo(document.querySelector('#sobre'),{immediate:true})");page.wait_for_function('!document.querySelector("#casa").houseJourney.inspect().view.dragging');page.mouse.up()
  check('sair durante o arraste solta a captura do ponteiro',not state(page)['view']['dragging'])
  c.close()
  c,page=open_page(b,390,844,mobile=True);go(page,.72)
  check('celular mantém gesto vertical livre antes de ativar',page.locator('.page3-canvas').evaluate('e=>getComputedStyle(e).touchAction')=='pan-y')
  page.locator('.page3-look-toggle').tap();check('botões oferecem alvo de toque de 44 pixels',page.locator('.page3-look-reset').bounding_box()['height']>=44)
  y=page.evaluate('scrollY');cdp=c.new_cdp_session(page)
  cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':80,'y':330}]})
  for x in [110,150,200,250,300]:cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':x,'y':360}]})
  cdp.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});settle(page)
  check('toque gira a câmera sem mover a página no modo de olhar',state(page)['view']['yaw']>2 and abs(page.evaluate('scrollY')-y)<2,state(page)['view'])
  page.screenshot(path=str(OUT/'look-touch-390.png'))
  page.locator('.page3-look-reset').tap();settle(page)
  check('voltar no celular devolve a rolagem vertical',page.locator('.page3-canvas').evaluate('e=>getComputedStyle(e).touchAction')=='pan-y' and not state(page)['view']['active'])
  y=page.evaluate('scrollY');cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':180,'y':500}]})
  for yy in [460,420,380,330]:cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':180,'y':yy}]})
  cdp.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});page.wait_for_function('y=>scrollY>y+20',arg=y)
  check('gesto vertical real volta a rolar no celular',True)
  page.evaluate("()=>__hipocampoLenis.scrollTo(document.querySelector('#sobre'),{immediate:true})");page.wait_for_function('document.querySelector(".page3-look-controls").hidden');check('controles não vazam para a página seguinte no celular',True)
  c.close()
  c,page=open_page(b,1366,768,reduced=True);page.evaluate("()=>__hipocampoLenis.scrollTo(document.querySelector('#casa'),{immediate:true})");page.wait_for_function('document.querySelector("#casa").houseJourney.inspect().view.available')
  page.locator('.page3-look-toggle').click();page.locator('.page3-look-toggle').press('ArrowLeft');settle(page)
  check('movimento reduzido permite olhar por teclado',state(page)['view']['yaw']>.1)
  page.locator('.page3-look-reset').click();settle(page);page.wait_for_timeout(100)
  check('movimento reduzido não mantém animação contínua',not state(page)['framePending'])
  page.locator('.page3-canvas').dispatch_event('webglcontextlost',{'cancelable':True});page.wait_for_function('document.querySelector("#casa").hidden')
  check('perda de contexto fecha controles e libera a navegação',page.locator('.page3-look-controls').is_hidden() and not state(page)['view']['active'])
  c.close();b.close()
 check('sem exceções JavaScript',not r['errors'],r['errors']);check('sem recursos locais faltando',not r['assets'],r['assets'])
finally:(OUT/'results.json').write_text(json.dumps(r,ensure_ascii=False,indent=2))
